        a_command->type = ET_CHAR;
        a_command->state = CS_UNDEFINED;
        a_command->u.my_char.user_data = user_data;
        a_command->u.my_char.unique_identifier = ++my_current_text_id;
        a_command->u.my_char.character = character;

        return a_command;
}

